import {jest} from '@jest/globals';
import {WebSocket} from 'ws';
import {createMessageHandler} from './messageHandler.js';
import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
import type {ChatSession, SessionEntry} from '../../types/session.js';
import type {OutgoingMessage} from '../../types/messages.js';
import {deferred} from '../wsTestSupport.js';

// Map frames to descriptive strings for readability
const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'error') return `error ${frame.code} ${frame.message}`;
    if (frame.type === 'conversation_list') {
      return `conversation_list ${frame.conversations.length} summaries`;
    }
    if (frame.type === 'stream_end') return 'stream_end';
    return frame.type;
  });

const harness = (orchestrator: ChatOrchestrator, mockSessionStore?: any) => {
  const sent: OutgoingMessage[] = [];
  const ws = {
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
    readyState: WebSocket.OPEN,
  } as unknown as WebSocket;

  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const handle = createMessageHandler(orchestrator);

  return {
    session,
    sent,
    frames: () => wire(sent),
    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
      handle(ws, session, raw, signal),
  };
};

describe('list_conversations over WebSocket', () => {
  describe('validation', () => {
    it('accepts list_conversations with no parameters as valid', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations'});

      // Should not error on validation alone (may error on handling if not configured, but that is separate)
      const hasValidationError = h.frames().some(f => f.includes('INVALID_MESSAGE'));
      expect(hasValidationError).toBe(false);
    });

    it('accepts list_conversations with valid limit (1-200)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 10});

      const hasValidationError = h.frames().some(f => f.includes('INVALID_MESSAGE'));
      expect(hasValidationError).toBe(false);
    });

    it('rejects list_conversations with invalid limit (0)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 0});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with invalid limit (201)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 201});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with non-integer limit (1.5)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 1.5});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with string limit ("10")', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: '10'});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('accepts list_conversations with valid before (ISO date string)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      const isoDate = '2025-01-15T12:00:00.000Z';
      await h.send({type: 'list_conversations', before: {updatedAt: isoDate, sessionId: 'sess123'}});

      const hasValidationError = h.frames().some(f => f.includes('INVALID_MESSAGE'));
      expect(hasValidationError).toBe(false);
    });

    it('rejects list_conversations with invalid before ("not a date")', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', before: 'not a date'});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });
  });

  describe('conversation_list response', () => {
    it('with history enabled and store returning conversations, sends conversation_list with ISO date strings', async () => {
      const conversations = [
        {
          sessionId: 'sess1',
          createdAt: new Date('2025-01-10T10:00:00Z'),
          updatedAt: new Date('2025-01-15T15:00:00Z'),
          entryCount: 5,
        },
        {
          sessionId: 'sess2',
          createdAt: new Date('2025-01-05T10:00:00Z'),
          updatedAt: new Date('2025-01-14T14:00:00Z'),
          entryCount: 3,
        },
        {
          sessionId: 'sess3',
          createdAt: new Date('2025-01-01T10:00:00Z'),
          updatedAt: new Date('2025-01-12T12:00:00Z'),
          entryCount: 1,
        },
      ];

      const mockStore = {
        listFor: jest.fn().mockResolvedValue(conversations),
      };

      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator, mockStore);
      // TODO: will need to inject store and history config into message handler
      // For now, this test shows what shape we expect

      await h.send({type: 'list_conversations'});

      // TODO: assertion will be: conversation_list frame with 3 summaries, dates as ISO strings, no stream_end
      expect(h.frames()).toContain('conversation_list 3 summaries');
      expect(h.frames()).not.toContain('stream_end');
    });

    it('uses ws.userId, not userId from frame, when calling listFor', async () => {
      const mockStore = {
        listFor: jest.fn().mockResolvedValue([]),
      };

      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator, mockStore);
      const session = h.session;
      session.userId = 'u1';

      // TODO: frame carries another user's id
      await h.send({type: 'list_conversations', userId: 'u2'});

      // TODO: assertion will verify listFor was called with 'u1' (ws.userId), not 'u2'
      // This requires injecting store into handler
    });

    it('passes limit and before to listFor unchanged', async () => {
      const mockStore = {
        listFor: jest.fn().mockResolvedValue([]),
      };

      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator, mockStore);

      const cursor = {updatedAt: '2025-01-15T12:00:00Z', sessionId: 'sess1'};
      // TODO: frame with limit and before
      await h.send({type: 'list_conversations', limit: 10, before: cursor});

      // TODO: assertion will verify listFor was called with {limit: 10, before: cursor}
    });
  });

  describe('error handling', () => {
    it('returns UNSUPPORTED error when history is not enabled', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      // TODO: need to inject history config set to disabled
      await h.send({type: 'list_conversations'});

      // TODO: assertion will check for error frame with code UNSUPPORTED
      expect(h.frames()).toContain('error UNSUPPORTED');
    });

    it('returns UNSUPPORTED error when store does not implement listFor', async () => {
      const mockStore = {}; // no listFor method

      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator, mockStore);
