// Map frames to descriptive strings for readability
const wire = (sent: OutgoingMessage[]): string[] =>
  sent.map(frame => {
    if (frame.type === 'error') return `error ${frame.code} ${frame.message}`;
    if (frame.type === 'conversation_list') {
      return `conversation_list ${frame.conversations.length} summaries`;
    }
    if (frame.type === 'stream_end') return 'stream_end';
    return frame.type;
  });

const harness = (orchestrator: ChatOrchestrator, mockSessionStore?: any) => {
  const sent: OutgoingMessage[] = [];
  const ws = {
    send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage),
    readyState: WebSocket.OPEN,
  } as unknown as WebSocket;

  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const handle = createMessageHandler(orchestrator);

  return {
    session,
    sent,
    frames: () => wire(sent),
    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
      handle(ws, session, raw, signal),
  };
};

describe('list_conversations over WebSocket', () => {
  describe('validation', () => {
    it('accepts list_conversations with no parameters as valid', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations'});

      // Should not error on validation alone (may error on handling if not configured, but that is separate)
      const hasValidationError = h.frames().some(f => f.includes('INVALID_MESSAGE'));
      expect(hasValidationError).toBe(false);
    });

    it('accepts list_conversations with valid limit (1-200)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 10});

      const hasValidationError = h.frames().some(f => f.includes('INVALID_MESSAGE'));
      expect(hasValidationError).toBe(false);
    });

    it('rejects list_conversations with invalid limit (0)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 0});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with invalid limit (201)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 201});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with non-integer limit (1.5)', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: 1.5});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

    it('rejects list_conversations with string limit ("10")', async () => {
      const orchestrator = {
        processMessageStream: async function* () {},
      } as unknown as ChatOrchestrator;

      const h = harness(orchestrator);
      await h.send({type: 'list_conversations', limit: '10'});

      const errorFrame = h.frames().find(f => f.includes('INVALID_MESSAGE'));
      expect(errorFrame).toBeDefined();
    });

